window.DGNL_DE_MON["l7"] = {"id": "l7", "ten": "Đề thi thử số 7", "tv": [{"noiDungChung": null, "cauHoi": [{"question": "<br><i>“Vua trên trời là Ngọc Hoàng có hai con gái đẹp. Ngọc Hoàng yêu quý hai nàng lắm nên cho các nàng hàng ngày luân phiên nhau đi xem xét mọi việc của hạ giới để báo lại cho nhà Trời. </i><br><i>Cô gái đầu tên là Mặt Trời được ngồi kiệu hoa có bốn người khiêng. Bốn người này chia làm hai tốp: một tốp già và một tốp trẻ. Tốp các cụ già khiêng kiệu luôn luôn lo làm tròn phận sự, chăm chỉ vào công việc nên cô Mặt Trời thường đi một vòng rất nhanh. Còn tốp trẻ bản tính la cà nên những lần được phân công khiêng kiệu thường về muộn. Vì thế, mỗi lần Mặt Trời đi với tốp trẻ thì ngày dài, và đi với tốp già thì ngày lại ngắn.” </i><br>(Trích thần thoại Việt Nam về <i>Nữ thần mặt trời và mặt trăng</i>)<br>Dựa theo đoạn trích, tốp người trẻ khiêng kiệu sẽ ứng với mùa nào trong năm nhất theo khí hậu Việt Nam?", "choices": ["Mùa xuân", "Mùa hạ", "Mùa thu", "Mùa đông"], "correctIndex": 1, "explain": "<b>Đáp án: B. Mùa hạ </b><br><b>Giải thích: </b>Mùa ngày dài hơn đêm một cách rõ ràng là mùa hạ theo khí hậu của Việt Nam ta."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>Phiên âm:</i><br><i>Cố nhân tây từ Hoàng Hạc lâu,</i><br><i>Yên hoa tam nguyệt há Dương Châu.</i><br><i>Cô phàm viễn ảnh bích không tận,</i><br><i>Duy kiến Trường Giang thiên tế lưu.</i><br><i>Dịch nghĩa:</i><br><i>Bạn cũ từ biệt tại lầu Hoàng Hạc đi về phía tây,</i><br><i>Tháng ba hoa khói, xuống Dương Châu.</i><br><i>Bóng chiếc buồm lẻ phía xa dần khuất vào trong nền trời xanh,</i><br><i>Chỉ còn thấy dòng Trường Giang vẫn chảy bên trời.</i><br>(Lý Bạch, <i>Hoàng Hạc lâu tống Mạnh Hạo Nhiên chi Quảng Lăng</i>)<br>Nhận định nào sau đây <b>không đúng </b>khi nói về tác phẩm trên?", "choices": ["Là một tác phẩm chuẩn mực của thơ Đường luật", "Thể hiện tình bằng hữu sâu đậm, thiết tha", "Không phải là một bài thơ thất ngôn tứ tuyệt Đường luật hoàn chỉnh", "Phảng phất màu sắc của tư tưởng Đạo gia trong lời thơ"], "correctIndex": 0, "explain": "<b>Đáp án: A. Là một tác phẩm chuẩn mực của thơ Đường luật </b><br><b>Giải thích: </b>Bài thơ trên không chuẩn mẫu và hoàn chỉnh vì vi phạm quy tắc luật bằng trắc ngay ở câu đầu tiên: chữ thứ 2 và chữ thứ 4 đều là thanh bằng (nhân - từ), trong khi đúng luật phải là một trắc - một bằng."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br><i>“Rồi vừa đi vừa ca rằng:</i><br><i>Sông Đằng một dải dài ghê,</i><br><i>Sóng hồng cuồn cuộn tuôn về bể Đông.</i><br><i>Những người bất nghĩa tiêu vong,</i><br><i>Nghìn thu chỉ có anh hùng lưu danh!”</i><br><i>Khách cũng nối tiếp mà ca rằng:</i><br><i>“Anh minh hai vị thánh quân,</i><br><i>Sông đây rửa sạch mấy lần giáp binh.</i><br><i>Giặc tan muôn thuở thanh bình,</i><br><i>Bởi đâu đất hiểm, cốt mình đức cao.”</i><br>(Trương Hán Siêu, <i>Bạch Đằng giang phú, </i><br>bản dịch của Đông Châu - Bùi Văn Nguyên)<br>Nhận định nào sau đây <b>không đúng </b>về đoạn trích trên?", "choices": ["Đề cập tới những cuộc kháng chiến lớn của dân tộc", "Thể hiện tinh thần “thi dĩ ngôn chí, văn dĩ tải đạo”", "Áng thơ mang trong mình dấu ấn lịch sử sâu đậm", "Sử dụng kết cấu đối đáp trong đoạn trích"], "correctIndex": 2, "explain": "<b>Đáp án: C. Áng thơ mang trong mình dấu ấn lịch sử sâu đậm </b><br><b>Giải thích: </b>Đây không phải một áng thơ vì Phú không phải một thể thơ."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>Xấp xỉ ba mươi mấy tuổi đầu,<br>Trăm năm tính đốt hẳn còn lâu.<br>Ví cho thi đỗ làm quan lớn,<br>Thì cũng nhỏ to cưới chị hầu!<br>Đất nọ vẫn thường hay có chạch,<br>Bể kia có lúc cũng trồng dâu.<br>Hôm nay rỗi rãi buồn tình nhỉ,<br>Thử xuống Hàng Thao đập ngón chầu.<br>(Trần Tế Xương, Cảm hứng)<br>Theo quy định niêm của thơ Đường luật, cụm “mấy tuổi đầu” sẽ niêm với cụm nào sau đây?", "choices": ["hẳn còn lâu", "làm quan lớn", "hay có chạch", "đập ngón chầu"], "correctIndex": 3, "explain": "<b>Đáp án: D. đập ngón chầu </b><br><b>Giải thích: </b>Theo luật niêm, câu 8 sẽ niêm với câu 1."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu/ đoạn thơ nào sau đây mô tả một mùa thu hoàn tất?", "choices": ["Ve kêu rừng phách đổ vàng/ Nhớ cô em gái hái măng một mình (Tố Hữu)", "Lá xanh nhuộm đã thành cây lá vàng (Nguyễn Bính)", "Trong vườn sắc đỏ rũa màu xanh (Xuân Diệu)", "Đầu tường lửa lựu lập lòe đơm bông (Nguyễn Du)"], "correctIndex": 1, "explain": "<b>Đáp án: B. <i>Lá xanh nhuộm đã thành cây lá vàng </i>(Nguyễn Bính) </b><br><b>Giải thích: </b>Ở đây mô tả cả một quá trình từ khi cây còn xanh lá tới khi cây đã hoàn toàn nhuộm vàng, tức mùa thu đã hoàn toàn xâm chiếm không gian."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đoạn thơ nào sau đây chứa hình ảnh mang đậm tính tượng trưng?", "choices": ["Sao anh không về chơi thôn Vĩ/ Nhìn nắng hàng cau nắng mới lên (Hàn Mặc Tử)", "Nắng mưa là chuyện của trời/ Tương tư là bệnh của tôi yêu nàng (Nguyễn Bính)", "Thuyền về nước lại sầu trăm ngả/ Củi một cành khô lạc mấy dòng (Huy Cận)", "Ôi sáng xuân nay, Xuân 41/ Trắng rừng biên giới nở hoa mơ (Tố Hữu)"], "correctIndex": 2, "explain": "<b>Đáp án: C. <i>Thuyền về nước lại sầu trăm ngả/ Củi một cành khô lạc mấy dòng </i>(Huy Cận) </b><br><b>Giải thích: </b>Thơ có tính tượng trưng là hình ảnh thơ phải mang ý nghĩa biểu tượng, diễn đạt một thông điệp độc đáo nào đó bên cạnh nét nghĩa trực quan của nó. Hình ảnh nhành củi bé nhỏ trôi giữa mênh mông muôn dòng gợi ra nỗi quan hoài về thân phận con người nhỏ bé giữa mênh mông dòng đời."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu/ đoạn thơ nào sau đây có sử dụng bút pháp tương giao?", "choices": ["Đã nghe rét mướt luồn trong gió (Xuân Diệu)", "Thuyền ai đậu bến sông trăng đó (Hàn Mặc Tử)", "Tôi muốn tắt nắng đi/ Cho màu đừng nhạt mất (Xuân Diệu)", "Sóng cỏ xanh tươi gợn tới trời/ Bao cô thôn nữ hát trên đồi (Hàn Mặc Tử)"], "correctIndex": 0, "explain": "<b>Đáp án: A. <i>Đã nghe rét mướt luồn trong gió </i>(Xuân Diệu) </b><br><b>Giải thích: </b>Bút pháp tương giao đặc biệt nổi bật ở điểm cảm nhận thế giới bằng sự giao hòa giữa các giác quan. Ở câu thơ của Xuân Diệu, cái lạnh (xúc giác, cảm giác) đã được cảm nhận bằng âm thanh qua động từ “nghe” (thính giác) và hình ảnh qua động từ “luồn” (thị giác)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“<i>Vật mình vẫy gió tuôn mưa, </i><br><i>Dầm dề giọt ngọc thẫn thờ hồn mai. </i><br><i>Đau đòi đoạn ngất đòi thôi, </i><br><i>Tỉnh ra lại khóc khóc rồi lại mê.” </i><br>(Nguyễn Du, <i>Truyện Kiều</i>)<br>Nhận định nào <b>không đúng </b>về đoạn trích trên?", "choices": ["Kế thừa được trọn vẹn thể thơ dân tộc", "Thể hiện được sâu sắc cảm xúc của nhân vật", "Sử dụng bút pháp ước lệ điêu luyện", "Không tuân thủ quy chuẩn của thể lục bát"], "correctIndex": 0, "explain": "<b>Đáp án: A. Kế thừa được trọn vẹn thể thơ dân tộc </b><br><b>Giải thích: </b>Đoạn thơ trên không kế thừa một cách trọn vẹn mà có sự phá cách trong cách ngắt nhịp. Lục bát truyền thống luôn ngắt nhịp chẵn (2/2/2 hoặc 4/2, 2/4 với câu 6; 2/2/2/2 hoặc 4/4, 4/2/2 với câu 8) nhưng ở đây câu lục “Đau đòi đoạn/ ngất đòi thôi” lại ngắt nhịp lẻ (nhịp 3/3)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu/ đoạn thơ nào sau đây mang dấu ấn siêu thực?", "choices": ["Ngày mai trong đám xuân xanh ấy/ Có kẻ theo chồng bỏ cuộc chơi (Hàn Mặc Tử)", "Em về trắng đầy cong khung nhớ (Lê Đạt)", "Áo em trắng quá nhìn không ra (Hàn Mặc Tử)", "Hãy cho tôi một tinh cầu giá lạnh/ Một vì sao trơ trọi cuối trời xa!"], "correctIndex": 1, "explain": "(Chế Lan Viên)<br><b>Đáp án: B. <i>Em về trắng đầy cong khung nhớ </i>(Lê Đạt) </b><br><b>Giải thích: </b>Dấu ấn siêu thực biểu hiện ở việc kết hợp các hình ảnh, từ ngữ mà không tuân thủ theo bất cứ logic thông thường nào. Ở đây có thể thấy sự phi logic trong việc kết hợp các từ “trắng - đầy - cong - khung - nhớ”, những từ tưởng như không liên quan đến nhau (màu sắc không liên quan đến sức nặng, nỗi nhớ vô hình không thể hiện hữu trong một khuôn khổ hữu hình)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“Thử tính lại diễn khơi ngày ấy<br>Tiền sen này đã nẩy là ba<br>Xót người lần lữa ải xa,<br>Xót người nương chốn Hoàng hoa dặm dài.”<br>(Chinh phụ ngâm khúc, Đặng Trần Côn<br>- bản dịch của Đoàn Thị Điểm)<br>Nhận định nào sau đây là đúng khi nói về nội dung đoạn trích trên?", "choices": ["Phản ánh tội ác của hôn nhân ép gả thời phong kiến", "Khắc họa được chân dung người chinh phụ chờ chồng", "Thời gian xa nhau thấm thoắt đã sang năm ba", "Nỗi nhớ chồng của người chinh phụ đã kéo dài được ba tháng"], "correctIndex": 2, "explain": "<b>Đáp án: C. Thời gian xa nhau thấm thoắt đã sang năm ba </b><br><b>Giải thích: </b>Thể hiện qua câu “Tiền sen nay đã nảy là ba”, tức đã ba mùa sen nở từ lúc chia xa - đồng nghĩa với đã sang năm thứ ba kể từ ngày ly biệt."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“Những ngày này nhớ và thương Quỳnh lắm, không nên bực bội về Sài Gòn và người Sài Gòn làm gì. Mùa đông này, về với anh, đi bên anh, nằm bên anh trong căn phòng đầy tranh của chúng ta. Và với Mí tuyệt vời của chúng ta. Và chúng ta sẽ viết chứ, sợ gì em nhỉ ?”<br>(Lưu Quang Vũ, <i>Thư tay gửi Xuân Quỳnh</i>)<br>Phong cách ngôn ngữ của đoạn trích trên là gì?", "choices": ["Nghệ thuật", "Hành chính", "Sinh hoạt", "Báo chí"], "correctIndex": 2, "explain": "<b>Đáp án: C. Sinh hoạt </b><br><b>Giải thích: </b>Thư từ thuộc về nhóm các văn bản sử dụng phong cách ngôn ngữ sinh hoạt."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Đâu là tên hiệu chính xác của Nguyễn Du?", "choices": ["Tố Như", "Tố Tâm", "Thanh Hiên", "Thanh Liên"], "correctIndex": 2, "explain": "<b>Đáp án: C. Thanh Hiên </b><br><b>Giải thích: </b>Thanh Hiên là tên hiệu, Tố Như là tên tự của Nguyễn Du."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>Hỡi tâm hồn, đừng chìm trong ưu sầu,<br>Sức sống này là ánh sáng, là niềm tin,<br>Muốn ăn gì, thì cứ đắm đuối mà tìm,<br>Làm sao từ chối khi sắc đẹp không chờ đợi?<br>(Phạm Trường Giang, <i>Áng mây lặng lẽ</i>)<br>Có bao nhiêu từ láy trong đoạn thơ trên?", "choices": ["Không có từ láy", "1", "2", "Nhiều hơn 2 từ láy"], "correctIndex": 0, "explain": "<b>Đáp án: A. Không có từ láy </b><br><b>Giải thích: </b>Không có từ nào là từ láy trong đoạn trên."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Dòng nào sau đây chứa các từ viết đúng chính tả?", "choices": ["Bôi bác, cọ sát, xừng sỏ", "Bôi bát, cọ sát, sừng xỏ", "Bôi bác, cọ xát, xừng xỏ", "Bôi bác, cọ xát, sừng sỏ"], "correctIndex": 3, "explain": "<b>Đáp án: D. Bôi bác, cọ xát, sừng sỏ </b><br><b>Giải thích: </b>Đây là cách viết đúng của các từ này."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Gã tiều phu vác trên lưng hai bó củi, khoan thai xuống núi.”<br>Từ nào sau đây có hiện tượng chuyển loại?", "choices": ["Gã", "hai", "bó", "núi"], "correctIndex": 2, "explain": "<b>Đáp án: C. bó </b><br><b>Giải thích: </b>Bó vốn là động từ nhưng ở đây được chuyển làm danh từ chỉ đơn vị."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "<br>“Cái cò là cái cò kỳ,<br>Ăn cơm nhà ____, uống nước nhà cô.<br>Đêm nằm thì ngáy o o,<br>Chửa đi đến chợ đã ___ ăn quà.”<br>(Ca dao Việt Nam)<br>Cặp từ nào sau đây thích hợp để điền vào phần còn trống trong bài ca dao trên?", "choices": ["bà - cho", "mi - cho", "dì - lo", "chị - lo"], "correctIndex": 2, "explain": "<b>Đáp án: C. dì - lo </b><br><b>Giải thích: </b>theo luật gieo vần và bằng trắc của thơ lục bát, từ đầu tiên cần điền phải có vần với chữ “kỳ” ở câu đầu, từ thứ hai cần điền phải có vần với tiếng “o” ở câu thứ ba, và cả hai từ đều phải mang thanh bằng. Đáp án C là đáp án duy nhất đáp ứng được cả về vần điệu và ngữ nghĩa."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm câu đúng trong số các câu sau?", "choices": ["Không còn ai trên đời thương xót cho hắn nữa.", "Biết bao điều chưa nói, cô gửi tặng cả trong bức thư này.", "Tía mở vang nước, bắt đầu tưới cho cây cối trong vườn.", "Cô ấy chẳng những tốt bụng và còn xinh đẹp nữa."], "correctIndex": 0, "explain": "<b>Đáp án: A. Không còn ai trên đời thương xót cho hắn nữa. </b><br><b>Giải thích: </b><br>B dùng sai từ <i>gửi tặng</i>.<br>C dùng sai từ <i>vang</i>.<br>D dùng sai quan hệ từ <i>và</i>."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Nhất sinh hắn không cầu phú quý, không cầu công danh, chỉ cầu một đời an vị, vì hắn không muốn tranh đấu với đời.”<br>Câu trên mắc lỗi sai nào?", "choices": ["Sai về phong cách", "Dùng từ sai nghĩa", "Sai về hệ quy chiếu", "Không có lỗi sai"], "correctIndex": 1, "explain": "<b>Đáp án: B. Dùng từ sai nghĩa </b><br><b>Giải thích: </b>Từ bị dùng sai là “an vị” (ngồi yên một chỗ). Cần sử <i>thành an </i>ổn hoặc <i>an nhiên </i>thì mới đúng nghĩa của câu."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "“Hắn nghĩ rằng mình sẽ không thể vượt qua kì thi này.”<br>Nhận định nào về câu trên là sai?", "choices": ["Câu trên chỉ có một cụm chủ - vị nòng cốt", "Câu trên có nhiều hơn một cụm chủ - vị", "Câu trên không mắc lỗi chính tả", "Câu trên chưa tường minh về nghĩa"], "correctIndex": 3, "explain": "<b>Đáp án: D. Câu trên chưa tường minh về nghĩa </b><br><b>Giải thích: </b>Nghĩa của câu trên đã tường minh.<br>A đúng vì câu chỉ có 1 cụm chủ vị chính (<i>Hắn </i>là chủ ngữ, phần còn lại là vị ngữ)<br>B đúng vì ngoài cụm chủ vị chính thì câu còn có 1 cụm chủ vị phụ trong vị ngữ (<i>mình sẽ không thể vượt qua kì thi này</i>)<br>C đúng vì câu không mắc lỗi chính tả."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Câu nào sau đây là câu <b>sai</b>?", "choices": ["Chuyện anh làm anh nên chịu trách nhiệm, chớ có vu oan cho người khác.", "Vầng trăng tròn trịa đang từ từ nhô lên ở phía nam.", "Mẹ nó quá chiều chuộng nó, vô hình trung đã làm nó trở nên hư hỏng.", "Hắn ta quả là một kẻ vụng chèo khéo chống."], "correctIndex": 1, "explain": "<b>Đáp án: B. Vầng trăng tròn trịa đang từ từ nhô lên ở phía nam. </b><br><b>Giải thích: </b>Sai ngữ nghĩa. Vầng trăng cũng như mặt trời, mọc lên từ phương đông chứ không phải phương nam."}], "khongXaoTron": true}, {"noiDungChung": "Tri phủ Thanh Hóa Lê Mỗ kính thư gửi quan tổng binh Thành Sơn hầu biết:<br>(1) Tôi nghe cái điều đáng quý ở người tuấn kiệt là biết thời thế, hiểu sự biến mà thôi. Xem ta ngày xưa ở Khả Lam, đất chẳng qua một thành, quân chẳng qua một lữ, mà thường bị bọn Mã Kỳ, Chu Kiệt bức; sau lại phải trốn ở núi Chí Linh đất Lão Qua để đợi thời mà ra, cơm ăn chẳng nề hai bữa, áo mặc chẳng nề đông hè, quân lính chỉ độ vài nghìn, khí giới thì như không trơn, thân thích con em thây bạn thì tân tắc quế người, không được sum họp. Thế mà bọn Phương Chính, Mã Kỳ, Vương Thành, Phùng Quý lại luôn năm tiến đánh, binh giáp của ta sớm hôm bố trí, không phút nghỉ ngơi. Song gặp khốn mà thông, càng đánh càng thẳng, đến đầu cũng là bẻ gãy đập tan, há chẳng phải lòng trời đấy sao!<br>(2) Ngày nay vận trời tuần hoàn, đi rồi lại lại. Trước kia ăn không nề hai bữa, mà nay thì với lương thực của các ngươi tích trữ, ăn được ba chục năm; trước kia quân bất quá vài trăm người, mà nay thì binh phụ tử ở Thanh Hóa không dưới hai vạn, quân có tiếng tinh tráng dũng cảm ở Diễn Châu, Tân Bình, Thuận Hóa cũng không dưới vài vạn, cùng quân đồng tâm đông lực ở các lộ Giao Châu, không dưới mười vạn người, trước thì thầy bạn thân thích tan tác, mà nay thì những kẻ sĩ trí mưu tài thức, không khác gì cây rừng rậm rạp, răng lược khít nhau; trước thì khi giới không trơn mà nay thì thuyền chiến ngất mây, áo giáp rực sáng, tên đạn chất đống, thuốc súng đầy kho. So trước với giờ, mạnh hay yếu thì biết rõ được. Huống chi ở nước ngươi, quốc chúa liền năm tử táng, cốt nhục tàn hại lẫn nhau, Bắc Khấu xâm lăng, đại thần lấn át; gia dĩ mùa màng mất luôn, thổ mộc làm mãi, chính lệnh hà khắc, giặc cướp như ong. Từ niên hiệu Hồng Vũ đến nay, cùng binh độc vũ trong nước tổn hao, nhân dân mệt nhọc. Trời làm táng vọng, chính ở lúc này.<br>(3) Ngươi còn không hiểu thời biến, lại nghe lời bọn Phương, Mã mà vẫn làm kế công thủ. Hẳn nếu giỏi công thủ thì sao không đánh ta ngay thuở ở Khả Lam hãy còn nhỏ yếu, mà bây giờ lại dương vây khoác lác như thế ư? Sao không biết nghĩ lắm thế? Huống chi lại bưng bít tai mắt người ta, đặt điều lừa phỉnh nói phao là viện binh sắp đến, Trương Phụ lại sang. Ngươi sao không nghĩ, ngày nay dẫu có mười vạn viện binh, thì có dám vượt cửa quan không? Ví bằng dốc quân cả nước kéo sang, hoặc độ ba bốn mươi vạn, thì sao ngươi không liệu nước ngươi ngày nay quả vô sự chăng? Như loại Trương Phụ, bất quá nhất thời hú họa thành công thôi. Bấy giờ họ Hồ thoán đoạt, người cả nước xem tựa kẻ thù, dân chúng chống lại, thân thích phần ly. Trương Phụ chỉ may nhân chỗ hở ấy mà thành công thôi. Ngươi sao không nghĩ, ta bình tượng nhiều, tâm lực đều, dù có trăm bọn Trương Phụ thì làm gì ta! Huống chi nước ngươi tình thế nguy ngập như thế, mà lại sai Trương Phụ đem ba bốn mươi vạn quân ra ngoài, liệu triều đình ngươi có yên tâm chăng?<br>(4) Nay tính giùm các ông, chẳng gì bằng cùng Thái đô đốc đem quần về nước là hơn cả. Không thế thì một khi cờ ta trỏ, trống ta nổi, các ông ăn năn chẳng kịp đâu! Kinh Dịch có câu: &quot;Cùng tắc biến, biến tắc thông&quot;. Các ông sao không nghĩ thế, cứ khư khư cái tiểu tiết của Trương Tuần, Hứa Viễn, ta e sĩ tốt của ngươi, ngày đêm tha thiết mong về, lại thêm cơm cháo chẳng no, tạp dịch liên tiếp, dẫu muốn đánh và giữ, đã dễ ai theo. Ngạn ngữ có câu: &quot;Một buổi không có ăn, cha con hết tình nghĩa&quot;. Vả bọn Phương Mã là tướng thua trận, không thể nói chuyện mạnh được, các ông nên nghĩ kỹ đi.<br>(Nguyễn Trãi, <i>Lại thư cho Vương Thông</i>)", "cauHoi": [{"question": "Người phát ngôn trong bức thư này là ai?", "choices": ["Nguyễn Trãi", "Chủ tướng nghĩa quân Lam Sơn", "Chủ tướng của quân giặc Minh", "Quốc chúa của quân giặc"], "correctIndex": 1, "explain": "<b>Đáp án: B. Chủ tướng nghĩa quân Lam Sơn </b><br><b>Giải thích: </b>Dù Nguyễn Trãi tự tay viết nhưng người phát ngôn được nêu rõ ở phần mở đầu chính là Lê Lợi (Tri phủ Thanh Hóa Lê Mỗ)."}, {"question": "Theo nội dung của bức thư, một trong những yếu tố quan trọng hàng đầu khiến quân ta có thể vững tin đương đầu với quân giặc là gì?", "choices": ["Lòng quân giặc không yên", "Đắc thiên ý", "Tướng giặc nhu nhược", "Địa hình có lợi"], "correctIndex": 1, "explain": "<b>Đáp án: B. Đắc thiên ý </b><br><b>Giải thích: </b>Yếu tố quan trọng này đã được lặp lại nhiều lần ở cả đoạn 1 và đoạn 2, cho thấy quân ta đang được lòng trời còn quân giặc bị trời làm táng vọng."}, {"question": "Đâu là tiền đề lập luận của bức thư trên?", "choices": ["Tinh thần chiến đấu của quân ta đang dâng cao", "Thời thế và sự xoay chuyển thời thế", "Quân giặc đang có những bất hòa trong nội bộ", "Quốc chúa của giặc liền năm tử táng"], "correctIndex": 1, "explain": "<b>Đáp án: B. Thời thế và sự xoay chuyển thời thế </b><br><b>Giải thích: </b>Tiền đề lập luận chính là cơ sở lí lẽ để người viết bám vào lập luận, Ở đây ngay từ câu đầu, người viết đã nêu rất rõ tiền đề lập luận chính là thời thế và quy luật xoay chuyển của thời thế “Tôi nghe cái điều đáng quý ở người tuấn kiệt là biết thời thế, hiểu sự biến mà thôi”."}, {"question": "Vì sao đoạn văn số (4) nhất thiết phải được đặt ở vị trí đó?", "choices": ["Vì lời khuyên sẽ có giá trị nhất khi đã phân tích đầy đủ các mặt", "Vì lời khuyên không thể xuất hiện ở ngay đầu tác phẩm", "Vì phải cân nhắc xem có nên đưa ra lời khuyên cho tướng giặc hay không", "Vì tránh lối viết “đầu voi đuôi chuột”, phần cuối cần có điểm nhấn"], "correctIndex": 0, "explain": "<b>Đáp án: A. Vì lời khuyên sẽ có giá trị nhất khi đã phân tích đầy đủ các mặt </b><br><b>Giải thích: </b>Lời khuyên được đặt tại vị trí này là hoàn toàn hợp lí khi đã phân tích được sức mạnh, tiềm lực quân sự của ta cũng như những khốn khó của địch ở phần trước đó."}, {"question": "Đâu là nhận xét đúng về giọng điệu của bức thư trên?", "choices": ["Giọng điệu thống nhất, đầy tự hào và tự tôn dân tộc", "Giọng điệu biến hóa, khi nhún nhường, khi hào sảng", "Giọng điệu xuyên suốt là giọng điệu của người bề trên nói với kẻ dưới", "Sử dụng xuyên suốt là giọng điệu đe dọa, thị uy quân giặc"], "correctIndex": 1, "explain": "<b>Đáp án: B. Giọng điệu biến hóa, khi nhún nhường, khi hào sảng </b><br><b>Giải thích: </b>Nguyễn Trãi mở đầu với sự nhún nhường trong cách xưng hô, sau đó lần lượt nêu rõ khí thế, sức mạnh của quân ta và thế yếu của quân giặc bằng một giọng điệu vô cùng hào sảng, và kết lại bằng một lời khuyên vừa tâm tình lại vừa đanh thép."}], "khongXaoTron": true}, {"noiDungChung": "Cảnh trời với lòng người như một đám rừng sâu thẳm, hoa cỏ hương thơm, sắc lạ vô cùng mà người đời là những khách vào rừng lại vì còn phải mưu cầu sự sống, nên chỉ lo bẻ măng đào củ, bao nhiêu cảnh đẹp, bao nhiêu hiện tượng li kì đều bỏ qua không biết, không thưởng thức.[...] Vén tấm màn đen ấy, tìm những cái hay, cái đẹp, cái lạ trong cảnh trí thiên nhiên và trong tâm linh người ta rồi mượn câu văn, tiếng hát, tấm đá, bức tranh làm cho người ta cùng nghe, cùng thấy, cùng cảm, đó là nhiệm vụ của nghệ thuật và, nói riêng ra, cũng là nhiệm vụ của văn chương.<br>Làm trọn nhiệm vụ ấy, nhà văn sẽ quên mình, thoát mình ra ngoài phạm vi hẹp hòi của bản thân để sống cái đòi của mọi người, mọi vật. Văn chương sẽ là hình dung của sự sống muôn hình vạn trạng. Chẳng những thế, văn chương còn sáng tạo ra sự sống Vũ trụ này tầm thường, chật hẹp, không đủ thỏa mãn mối tình cảm dồi dào của nhà văn? Nhà văn sẽ sáng tạo ra những thế giới khác, những người, những vật khác. Sự sáng tạo này cũng có thể xem là xuất ở mối tình yêu thương tha thiết. Yêu thương ngay những điều chưa có trong thực tế để gọi nó vào thực tế. [...] Những thế giới tưởng tượng trong văn chương cũng sáng tạo ra bởi lòng yêu thương vô cùng của nhà văn. Nếu có một người yêu Thuý Kiều còn nồng nàn hơn Kim Trọng, người ấy là Nguyễn Du và chính Nguyễn Du đã trao sự sống của mình cho thiếu nữ trong truyện.<br>Vậy thì, hoặc hình dung sự sống, hoặc sáng tạo ra sự sống, nguồn gốc của văn chương là tình cảm, là lòng vị tha. Và vì thế, công dụng của văn chương cũng là giúp cho tình cảm và gợi lòng vị tha.<br>(Hoài Thanh, <i>Ý nghĩa văn chương</i>)", "cauHoi": [{"question": "Đoạn văn <i>“Cảnh trời và lòng người … không biết thưởng thức” </i>có nội dung chính là gì?", "choices": ["Vẻ đẹp cuộc sống khó có thể được nhận ra bởi người đời", "Cuộc sống vốn luôn hiện hữu đầy vẻ diệu kì", "Con người vì quá mải mê trước vẻ đẹp diệu kì mà quên đi hiện thực", "Con người vì mải chạy theo những điều xa vời mà quên đi những thứ gần gũi trước mắt."], "correctIndex": 1, "explain": "<b>Đáp án: B. Cuộc sống vốn luôn hiện hữu đầy vẻ diệu kì </b><br><b>Giải thích: </b>Không phải cuộc sống không có vẻ đẹp mà theo tác giả, cuộc sống vốn có rất nhiều điều kì diệu nhưng con người vì còn phải lo bươn chải với đời nên không để ý và vô tình lãng quên chúng."}, {"question": "Theo đoạn trích, đâu là sứ mệnh được đặt ra cho người cầm bút?", "choices": ["Đem lại những trải nghiệm siêu thực cho người đọc", "Truyền tải những bài học đạo đức, lối sống thông qua tác phẩm", "Đưa đến cho người đọc những giá trị thẩm mĩ qua tác phẩm", "Không ngừng nỗ lực trau dồi khả năng viết lách của bản thân"], "correctIndex": 2, "explain": "<b>Đáp án: C. Đưa đến cho người đọc những giá trị thẩm mĩ qua tác phẩm </b><br><b>Giải thích: </b>Hoài Thanh nhấn mạnh sứ mệnh của nhà văn, của văn chương chính là “Vén tấm màn đen ấy, tìm những cái hay, cái đẹp, cái lạ trong cảnh trí thiên nhiên và trong tâm linh người ta rồi mượn câu văn, tiếng hát, tấm đá, bức tranh làm cho người ta cùng nghe, cùng thấy, cùng cảm”."}, {"question": "Đại kiệt tác nào đã được nhắc đến trong đoạn trích trên?", "choices": ["Kim Vân Kiều truyện", "Tỏa Nhị Kiều", "Đoạn trường tân thanh", "Những điều trông thấy mà đau đớn long"], "correctIndex": 2, "explain": "<b>Đáp án: C. Đoạn trường tân thanh </b><br><b>Giải thích: </b>Đoạn trường tân thanh là tên gọi khác của Truyện Kiều."}, {"question": "Câu văn cuối cùng của đoạn trích đề cập tới phạm trù nào của văn chương?", "choices": ["Chức năng", "Đặc trưng", "Nguồn gốc", "Bản chất"], "correctIndex": 0, "explain": "<b>Đáp án: A. Chức năng </b><br><b>Giải thích: </b>Câu văn cuối là câu “Và vì thế, công dụng của văn chương cũng là giúp cho tình cảm và gợi lòng vị tha.” . Ở đây có thể thấy xuất hiện từ “công dụng” và từ “giúp”, những từ khóa cho ta biết nó đang đề cập tới phạm trù chức năng của văn chương."}, {"question": "Quan niệm nào sau đây về văn chương nghệ thuật là sát nhất với nội dung của đoạn trích?", "choices": ["Văn chương là sáng tạo những điều chưa từng có", "Nhà văn là người thư kí trung thành của thời đại", "Văn học tái hiện để rồi tái tạo", "Văn học là nhân học"], "correctIndex": 2, "explain": "<b>Đáp án: C. Văn học tái hiện để rồi tái tạo </b><br><b>Giải thích: Tái hiện tức là phản ánh lại những gì cuộc sống đã có, tái tạo là làm lại, là tạo ra cả những điều cuộc sống đã có và chưa có. Đây chính là tinh thần mà Hoài Thanh muốn thể hiện và triển khai rất rõ trong đoạn trích.</b>"}], "khongXaoTron": true}], "anh": [{"noiDungChung": null, "cauHoi": [{"question": "<i class=\"huong-dan-cau\">Mark the letter A, B, C, or D on your answer sheet to indicate the correct answer to each of the following questions.</i><br>Before signing the contract, you need to go ______ it carefully to avoid any mistakes", "choices": ["over", "through", "about", "with"], "correctIndex": 1, "explain": "<b>31. B – through</b><br>Cụm động từ:<br>go over = xem lướt<br><b>go through = xem xét kỹ từng chi tiết</b><br>go about = bắt đầu làm gì<br>go with = đi cùng<br>Trước khi ký hợp đồng cần xem xét kỹ → <b>go through</b>."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "My father ______complete silence when he _______", "choices": ["wants; is working", "wanted; had worked", "wants, will work", "has wanted; works"], "correctIndex": 0, "explain": "Câu 32: A. wants; is working<br>Giải thích: * <i>Wants</i>: Động từ chỉ trạng thái (stative verb) như &quot;want&quot; hiếm khi dùng ở thì tiếp diễn.<br><i>Is working</i>: Diễn tả một hành động đang xảy ra tại thời điểm được nói đến (khi ông ấy đang làm việc thì ông ấy yêu cầu sự yên tĩnh)."}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Water pollution happens when chemicals and wastes are released into rivers, making the water ______ and unsafe for drinking.", "choices": ["polluted", "pollution", "pollute", "polluting"], "correctIndex": 0, "explain": "<b>Câu 33: A. polluted</b><br><b>Giải thích: Cấu trúc Make + Object + Adjective (Làm cho cái gì đó trở nên như thế nào). Ở đây &quot;polluted&quot; (bị ô nhiễm) đóng vai trò là tính từ bổ nghĩa cho &quot;the water&quot;.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "______ you get to the concert, ______the seat you have", "choices": ["the soonest; the best", "the sooner; the better", "sooner; better", "the soon; the good"], "correctIndex": 1, "explain": "<b>Câu 34: B. the sooner; the better</b><br><b>Giải thích: Cấu trúc so sánh càng... càng: The + comparative + S + V, the + comparative + S + V.</b>"}], "khongXaoTron": true}, {"noiDungChung": null, "cauHoi": [{"question": "Huong likes sweet tea. She usually adds ______ honey to her tea", "choices": ["few", "little", "a few", "a little"], "correctIndex": 3, "explain": "<b>Câu 35: D. a little</b><br><b>Giải thích: * &quot;Honey&quot; (mật ong) không đếm được nên loại <i>few/a few</i>.</b><br><b>Vì Hương thích trà ngọt nên cô ấy phải thêm &quot;một ít&quot; (nghĩa khẳng định) </b><span class=\"ct\">→</span><b> dùng a little. </b><br><b>Nếu dùng <i>little</i>, nó mang nghĩa &quot;hầu như không có&quot;.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 36-40: </b>Mark the letter A, B, C, or D on your answer sheet to indicate the wrong word use/form to each of the following statement.", "cauHoi": [{"question": "<u>A large</u> number of entries <u>has updated</u> in the latest edition <u>of</u> the encyclopedia <u>recently</u>.", "choices": ["A large", "has updated", "of", "recently."], "correctIndex": 1, "explain": "<b>Câu 36: B. has updated</b><br><b>Lỗi:</b> Sai cả về <b>Sự hòa hợp giữa chủ ngữ và động từ</b> lẫn <b>Thể bị động</b>.<br><b>Sửa lại:</b> <i>have been updated</i>.<br><b>Lý do:</b> * &quot;A large number of + N (số nhiều)&quot; luôn đi với động từ số nhiều.<br>&quot;Entries&quot; (các mục từ) không thể tự cập nhật mà phải &quot;được cập nhật&quot;."}, {"question": "Bowling, one <u>of the</u> most popular <u>indoor</u> sports, <u>are</u> popular all over the United States and in <u>other</u> countries.", "choices": ["of the", "indoor", "are", "other."], "correctIndex": 2, "explain": "<b>Câu 37: C. are</b><br><b>Sửa lại đúng:</b> <i>is</i>.<br><b>Tên các môn thể thao kết thúc bằng &quot;s&quot; (như Bowling, Billiards, Darts) luôn được coi là danh từ số ít.</b>"}, {"question": "<u>While</u> the campaign, young volunteers <u>help</u> build bridges, <u>roads</u> and houses for<br>some of Viet Nam&#x27;s most <u>disadvantaged</u> families.", "choices": ["While", "help", "roads", "disadvantaged."], "correctIndex": 0, "explain": "<b>38. A – While</b><br>“While the campaign” sai vì thiếu mệnh đề.<br>Sửa lại đúng: While they were campaigning… hoặc During the campaign…"}, {"question": "I saw <u>the</u> blind woman <u>crossed</u> the busy road <u>without</u> any <u>help</u>.", "choices": ["the", "crossed", "without", "help."], "correctIndex": 1, "explain": "<b>39. B – crossed</b><br>Sau “see” có 2 dạng:<br>see + O + V nguyên mẫu<br>see + O + V-ing<br>→ phải là “I saw the blind woman <b>cross</b> the road” Không dùng crossed."}, {"question": "Some people <u>say often</u> that <u>using cars</u> is not <u>so</u> convenient <u>as using motorbikes</u>.", "choices": ["say often", "using cars", "so", "as using motorbikes."], "correctIndex": 0, "explain": "<b>Câu 40: A. say often</b><br><b>Giải thích: Trạng từ chỉ tần suất (<i>often</i>) thường đứng trước động từ thường. Sửa thành: <i>often say</i>.</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 41-45: </b>Which of the following best restates each of the given sentences?", "cauHoi": [{"question": "“I agree that I am narrow–minded,” said the manager.", "choices": ["The manager denied being narrow–minded.", "The manager refused to be narrow–minded.", "The manager admitted being narrow–minded.", "The manager promised to be narrow–minded."], "correctIndex": 2, "explain": "<b>Câu 41: C. The manager admitted being narrow–minded.</b><br><b>Giải thích: &quot;I agree that I am...&quot; (Tôi đồng ý là tôi...) tương đương với một lời thừa nhận. Cấu trúc: Admit + V-ing/noun (Thừa nhận đã làm gì/như thế nào)</b>"}, {"question": "My personal opinion doesn’t really matter. You need to decide for the good of everyone.", "choices": ["Though my personal opinion really matters, we need to decide for the good for everyone.", "Deciding for the good of everyone makes our personal opinion not really matter at all.", "We need to decide for the good for everyone, so my personal opinion doesn’t really matter.", "If my personal opinion doesn’t really matter, we need to decide for the good of everyone."], "correctIndex": 2, "explain": "<b>Câu 42: C. We need to decide for the good for everyone, so my personal opinion doesn’t really matter.</b><br><b>Giải thích: Câu gốc đưa ra hai ý: ý kiến cá nhân không quan trọng và cần quyết định vì lợi ích chung. Đáp án C dùng liên từ &quot;so&quot; (vì vậy) để nối hai vế một cách logic nhất.</b>"}, {"question": "Most of the river ferries have been cancelled today due to the lack of visibility caused by the fog.", "choices": ["A few of the ferries need to be rescheduled because of the fog that is causing poor visibility on the river.", "Since today’s fog is obstructing visibility, the majority of the river ferries will not be running.", "Because of the fog, it will be difficult for most of the ferries to cross the river safely today.", "Whenever visibility is poor owing to the fog, nearly all of the river ferries are cancelled during the day."], "correctIndex": 1, "explain": "<b>Câu 43: B. Since today’s fog is obstructing visibility, the majority of the river ferries will not be running.</b><br><b>Giải thích: &quot;Most&quot; (phần lớn) đồng nghĩa với &quot;the majority&quot;. Cấu trúc &quot;Due to...&quot; (do) được chuyển thành &quot;Since...&quot; (vì).</b>"}, {"question": "It was a mistake for Tony to buy that house.", "choices": ["Tony couldn’t have bought that house", "Tony can’t have bought that house.", "Tony needn’t have bought that house.", "Tony shouldn’t have bought that house."], "correctIndex": 3, "explain": "<b>Câu 44: D. Tony shouldn’t have bought that house.</b><br><b>Giải thích: Cấu trúc Shouldn&#x27;t have + V3/ed dùng để chỉ một việc đáng lẽ không nên làm trong quá khứ nhưng đã làm (thể hiện sự hối tiếc hoặc lỗi sai).</b>"}, {"question": "He didn’t take his father’s advice. That’s why he is out of work now.", "choices": ["If he took his father’s advice, he would not be out of work now.", "If he had taken his father’s advice, he would not have been out of work now.", "If he had taken his father’s advice, he would not be out of work now.", "If he takes his father’s advice, he will not be out of work now."], "correctIndex": 2, "explain": "<b>Câu 45: C. If he had taken his father’s advice, he would not be out of work now.</b><br><b>Giải thích: Đây là câu điều kiện loại hỗn hợp (Mixed Conditional). Giả thiết trái với quá khứ (<i>had taken</i>) dẫn đến kết quả trái với hiện tại (<i>would not be... now</i>).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 46-52: Read the passage carefully and choose an option (A, B, C, or D) that best answers each question</b><br>No sooner had the first intrepid male aviators safely returned to Earth than it seemed that women, too, had been smitten by an urge to fly. From mere spectators, they became willing passengers and finally pilots in their own right, plotting their skills and daring lines against the hazards of the air and the <b>skepticism</b> of their male counterparts. In doing so they enlarged the traditional bounds of a women&#x27;s world, won for their sex a new sense of competence and achievement, and contributed handsomely to the progress of aviation.<br>But recognition of their abilities did not come easily. &quot;Men do not believe us capable.&quot; The famed aviator Amelia Earhart once remarked to a friend. &quot;Because we are women, seldom are we trusted to do an efficient job.&quot; Indeed old attitudes died hard: when Charles Lindbergh visited the Soviet Union in 1938 with his wife, Anne– herself a pilot and gifted proponent of aviation – he was astonished to discover both men and women flying in the Soviet Air Force.<br>Such conventional wisdom made it difficult for women to raise money for the up – to – date equipment they needed to compete on an equal basis with men. Yet they did compete, and often they triumphed finally despite the odds.<br>Ruth Law, whose 590 – mile flight from Chicago to Hornell, New York, set a new nonstop distance record in 1916, exemplified the resourcefulness and grit demanded of any woman who wanted to fly. And when she <b>addressed</b> the Aero Club of America after completing her historic journey, her plainspoken words testified to a universal human motivation that was unaffected by gender: &quot;My flight was done with no expectation of reward,&quot; she declared, &quot;just purely for the love of accomplishment.&quot;", "cauHoi": [{"question": "Which of the following is the best title for this passage?", "choices": ["A Long Flight", "Women in Aviation History", "Dangers Faced by Pilots", "Women Spectators"], "correctIndex": 1, "explain": "<b>Câu 46: B. Women in Aviation History (Tiêu đề phù hợp nhất vì bài viết nói về quá trình phụ nữ tham gia và đóng góp cho ngành hàng không).</b>"}, {"question": "According to the passage, women pilots were successful in all of the following EXCEPT", "choices": ["challenging the conventional role of women", "contributing to the science of aviation", "winning universal recognition from men", "building the confidence of women"], "correctIndex": 2, "explain": "<b>Câu 47: C. winning universal recognition from men (Trong bài, Amelia Earhart nói rằng đàn ông vẫn chưa thực sự tin tưởng: &quot;Men do not believe us capable&quot;).</b>"}, {"question": "What can be inferred from the passage about the United States Air Force in 1938?", "choices": ["It had no women pilots.", "It gave pilots handsome salaries.", "It had old planes that were in need of repair.", "It could not be trusted to do an efficient job."], "correctIndex": 0, "explain": "<b>Câu 48: A. It had no women pilots. (Chi tiết Lindbergh &quot;kinh ngạc&quot; khi thấy phụ nữ lái máy bay ở Liên Xô cho thấy ở Mỹ lúc đó điều này không tồn tại).</b>"}, {"question": "In their efforts to compete with men, early women pilots had difficulty in", "choices": ["addressing clubs", "flying nonstop", "setting records", "raising money"], "correctIndex": 3, "explain": "<b>Câu 49: D. raising money (Đoạn 3 có nêu: &quot;...made it difficult for women to raise money for the up-to-date equipment&quot;).</b>"}, {"question": "According to the passage, who said that flying was done with no expectation of reward?", "choices": ["Amelia Earhart", "Charles Lindbergh", "Anne Lindbergh", "Ruth Law"], "correctIndex": 3, "explain": "<b>Câu 50: D. Ruth Law (Câu cuối bài trích dẫn lời của Ruth Law: &quot;My flight was done with no expectation of reward&quot;).</b>"}, {"question": "The word ‘<b>skepticism</b>’ in paragraph 1 is closest in meaning to.", "choices": ["hatred", "doubt", "support", "surprise"], "correctIndex": 1, "explain": "<b>Câu 51: B. doubt (Skepticism = sự hoài nghi/nghi ngờ).</b>"}, {"question": "The word ‘<b>addressed’</b> in paragraph 4 can be best replaced by.", "choices": ["mailed", "came back to", "spoke to", "consulted"], "correctIndex": 2, "explain": "<b>Câu 52: C. spoke to (Address a club = diễn thuyết hoặc nói chuyện trước một câu lạc bộ).</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>Câu 53-60</b>: Read the passage carefully and Choose an option (A, B, C, or D) that best answers each question.<br>Scientists have identified two ways in which species disappear. The first is through ordinary or “background” extinctions, where species that fail to adapt are slowly replaced by more adaptable life forms. The second is when large numbers of species go to the wall in relatively short periods of biological time. There have been five such extinctions, each provoked by cataclysmic evolutionary events caused by some geological eruption, climate shift, or space junk slamming into the Earth.<br>Scientists now believe that another mass extinction of species is currently underway – and this time human fingerprints are on the trigger. How are we doing it? Simply by demanding more and more space for ourselves. In our <b>assault</b> on the ecosystems around us we have used a number of tools, from spear and gun to bulldozer and chainsaw. Certain especially rich ecosystems have proved the most vulnerable. In Hawaii more than half of the native birds are now gone – some 50 species. Such carnage has taken place all across the island communities of the Pacific and Indian oceans. While many species were hunted to extinction, others simply succumbed to the introduced predators that humans brought with <b>them</b>: the cat, the dog, the pig, and the rat.<br>Today the tempo of extinction is picking up speed. Hunting is no longer the major culprit, although rare birds and animals continue to be butchered for their skin, feathers, tusks, and internal organs, or taken as savage pets. Today the main threat comes from the destruction of the habitat of wild plants, animals, and insects need to survive. The draining and damming of wetland and river courses threatens the aquatic food chain and our own seafood industry. Overfishing and the destruction of fragile coral reefs destroy ocean biodiversity. Deforestation is taking a staggering toll, particularly in the tropics where the most global biodiversity is at risk. The shrinking rainforest cover of the Congo and Amazon river basins and such place as Borneo and Madagascar have a wealth of species per hectare existing nowhere else. As those precious hectares are drowned or turned into arid pasture and cropland, such species disappear forever.<br><i>(Source: Final Countdown Practice Tests by</i> <b><i>D.</i></b><i>F Piniaris, Heinle Cengage Learning, 2010)</i>", "cauHoi": [{"question": "What does the passage mainly discuss?", "choices": ["Human activity and its impact on a mass extinction of species", "The two ways in which species disappear", "The tempo of extinction of species today", "Deforestation as a major cause of mass extinctions of species"], "correctIndex": 1, "explain": "<b>Câu 53: B. Đoạn I: “Scientists have identified … disappear”, câu đầu tiên đã cho thấy được chủ đề của toàn bài.</b>"}, {"question": "The word <b>assault</b> in paragraph 2 is closest in meaning to.", "choices": ["development", "attack", "effort", "influence"], "correctIndex": 1, "explain": "<b>Câu 54: B. attack (Assault = cuộc tấn công, ở đây chỉ sự tàn phá của con người vào hệ sinh thái).</b>"}, {"question": "All of the following are mentioned as a form of habitat destruction EXCEPT", "choices": ["destroying coral reefs", "cutting down forests", "damming wetlands and rivers", "hunting rare birds and animals"], "correctIndex": 3, "explain": "<b>Câu 55: D. hunting rare birds and animals (Câu hỏi hỏi về &quot;phá hủy môi trường sống&quot; - Habitat destruction. Săn bắn là tác động trực tiếp lên con vật, không phải phá hủy nơi ở như đắp đập hay phá rừng).</b>"}, {"question": "What was the main threat to biodiversity in Hawaii and other islands in the Pacific and Indian oceans until recently?", "choices": ["tools used by human beings", "human assault on ecosystems", "vulnerable rich ecosystems", "hunters and introduced predators"], "correctIndex": 3, "explain": "<b>Câu 56: D. hunters and introduced predators (Đoạn 2 nêu nguyên nhân là do săn bắn và các động vật săn mồi do con người mang đến như mèo, chó, chuột...).</b>"}, {"question": "The word <b>them</b> in paragraph 2 refers to.", "choices": ["species", "oceans", "predators", "humans"], "correctIndex": 3, "explain": "<b>Câu 57: D. humans (Từ &quot;them&quot; ở cuối đoạn 2 thay thế cho danh từ &quot;humans&quot; ở phía trước).</b>"}, {"question": "Which is no longer considered a major cause of the mass extinction under way currently?", "choices": ["the building of dams across rivers", "the destruction of habitats of species", "the shrinking of rainforests in the tropics", "the killing of animals for their body parts"], "correctIndex": 3, "explain": "<b>Câu 58: D. the killing of animals for their body parts (Đoạn 3 câu đầu xác nhận: &quot;Hunting is no longer the major culprit&quot; - Săn bắn không còn là thủ phạm chính).</b>"}, {"question": "The word butchered in paragraph 3 is closest in meaning to.", "choices": ["raised", "traded", "cooked", "killed"], "correctIndex": 3, "explain": "<b>Câu 59: D. killed (Butchered = bị giết thịt/tàn sát).</b>"}, {"question": "It can be inferred from the passage that.", "choices": ["the current mass extinction is different from the other five in that it is caused by humans", "hunting is the major contributing factor that speeds up the extinction of species", "habitat destruction makes a minor contribution to the current mass extinction of species", "it’s impossible for scientists to identify the causes of mass extinctions of species"], "correctIndex": 0, "explain": "<b>Câu 60: A. Bài có đề cập chủ yếu qua các hoạt động của con người ảnh hưởng tới môi trường tự nhiên, ngoài các yếu tố tư nhiên được đề cập trong dòng cuối đoạn I. </b><br><b>Theo ý loại trừ: </b><br><b>B không phù hợp vì trong đoạn III đã nói rõ về hunting không còn là nguyên nhân chính.</b><br><b>C toàn bài có đề cập việc tàn phá môi trường sống của sinh vật tự nhiên là cái to lớn đánh vào sự tuyệt chủng của giống loài trên Trái Đất. Vì thế minor contribution là không phù hợp. </b><br><b>D. Đoạn I có câu đầu “Scientists have identified …” đã chứng minh được họ đã có nghiên cứu và tìm ra được nguyên nhân rồi. Trái với câu “it’s impossible …” </b>"}], "khongXaoTron": true}], "kh": [{"noiDungChung": "<b>MÔN HOÁ - Dựa vào thông tin dưới đây để trả lời các Câu từ 103 đến 105 </b><br>Khí carbon monoxide (CO) là khí không màu, không mùi được sinh ra khi các nhiên liệu như than, củi, xăng hoặc gas cháy không hoàn toàn. CO rất nguy hiểm vì khi hít phải, nó có thể gắn với hemoglobin trong máu làm giảm khả năng vận chuyển oxygen của cơ thể.<br>Nồng độ CO trong không khí thường được đo bằng ppm (parts per million). Theo khuyến cáo của World Health Organization, nồng độ CO trong không khí không nên vượt quá 9 ppm trong 8 giờ để đảm bảo an toàn sức khỏe.<br>Trong một phòng kín có thể tích 50 m³, người ta đo được lượng CO là 0,45 L khí CO (ở cùng điều kiện nhiệt độ và áp suất).<br>Biết: 1m<sup>3</sup> = 1000 L<br>Công thức tính gần đúng: <img class=\"anh-de\" src=\"data/anh/l7/d50809f8ce0fb64d.png\" alt=\"\" style=\"width:123px;height:49px;vertical-align:middle\">", "cauHoi": [{"question": "Đặc điểm nào sau đây khiến CO trở nên nguy hiểm?", "choices": ["Có màu vàng", "Có mùi hắc", "Không màu, không mùi nên khó nhận biết", "Tan rất nhiều trong nước"], "correctIndex": 2, "explain": "<span class=\"ct\"><b> ⇒ </b></span><b> Đáp án: C</b>"}, {"question": "Thể tích không khí trong phòng là:", "choices": ["5 000 L", "50 000 L", "500 000 L", "5 000 000 L"], "correctIndex": 1, "explain": "<span class=\"ct\"><b> ⇒ </b></span><b> Đáp án: B: 50 m<sup>3</sup> = 50 000 L</b>"}, {"question": "Nồng độ CO trong phòng gần nhất với giá trị nào?", "choices": ["0,9 ppm", "9 ppm", "90 ppm", "900 ppm"], "correctIndex": 1, "explain": "<span class=\"ct\"><b> ⇒ </b></span><b> Đáp án: B: </b>Thay vào công thức <img class=\"anh-de\" src=\"data/anh/l7/fa0a9b63d2d54c67.png\" alt=\"\" style=\"width:256px;height:49px;vertical-align:middle\">"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN LÝ - Dựa vào thông tin dưới đây để trả lời các Câu từ 106 đến 108 </b><br>Trong thực tế, nhiều thiết bị điện như hệ thống đèn tự động, máy bơm nước, chuông cửa, tủ lạnh, ô tô… cần dùng một mạch điều khiển công suất nhỏ để đóng/ngắt một mạch công suất lớn hơn. Để thực hiện điều đó một cách an toàn và cách ly điện, người ta sử dụng <b>Relay điện từ</b>. Relay cho phép dùng dòng điện nhỏ để điều khiển dòng điện lớn mà không cần nối trực tiếp hai mạch với nhau như hình minh hoạ bên dưới<br>Rơle điện từ 5 chân gồm:<br>Hai chân (1, 2) nối với <b>cuộn dây kích từ</b>.<br>Ba chân C (Common), NC (Normally Closed), NO (Normally Open).<br><table class=\"bang-de\"><tr><td>Khi <b>chưa cấp điện</b> vào cuộn dây:</td><td>Khi <b>cấp điện</b> vào cuộn dây:</td></tr><tr><td>C nối với NC (mạch thường đóng).<br>C không nối với NO (mạch thường mở).</td><td>Cuộn dây tạo ra từ trường.<br>Lõi sắt bị hút về phía cuộn dây.<br>Cần gạt chuyển vị trí tiếp điểm.<br>C nối với NO.<br>C tách khỏi NC.</td></tr></table><br>Như vậy, trạng thái tiếp điểm thay đổi nhờ tác dụng của từ trường do cuộn dây, khi cấp điện vào hai chân (1) và (2), cuộn dây đóng vai trò là một nam châm điện, hút tấm thép để điều khiển cần gạt tiếp xúc với mạch NC và NO.", "cauHoi": [{"question": "Relay điện từ trong các hệ thống điện – điện tử được sử dụng chủ yếu nhằm mục đích nào sau đây?", "choices": ["Làm tăng giá trị điện áp của nguồn điện cung cấp cho thiết bị tải so với điện áp ban đầu.", "Làm tăng cường độ dòng điện trong mạch bằng cách khuếch đại dòng điện đầu vào.", "Dùng một mạch điều khiển có điện áp và dòng điện nhỏ để điều khiển mạch có công suất lớn hơn, đồng thời đảm bảo cách ly điện giữa hai mạch.", "Tích trữ năng lượng điện dưới dạng từ trường để cung cấp lại cho mạch khi cần thiết."], "correctIndex": 2, "explain": ""}, {"question": "Khi cuộn dây relay chưa được cấp điện, trạng thái đúng của các tiếp điểm là:", "choices": ["Chân C nối với chân NO vì mạch đang ở trạng thái sẵn sàng hoạt động.", "Chân C đồng thời nối với cả NO và NC để đảm bảo dẫn điện liên tục.", "Chân C nối với chân NC là trạng thái mặc định khi chưa có từ trường tác dụng.", "Chân C không tiếp xúc với NO và NC, vì thế mạch không ở trạng thái hoạt động."], "correctIndex": 2, "explain": ""}, {"question": "Một hệ thống đèn hành lang 220V–3A được điều khiển bằng rơle (cuộn dây 12V–0,08A; tiếp điểm chịu tối đa 250V–5A). Theo dự tính mong muốn: ban ngày không cấp 12V nên đèn tắt, ban đêm cấp 12V thì đèn sáng. Tuy nhiên sau khi lắp đặt, ban ngày đèn lại sáng còn ban đêm thì tắt. Biết nguồn 220V ổn định, dòng 3A không vượt quá 5A và rơle không hỏng. Nguyên nhân hợp lý nhất là gì?", "choices": ["Relay bị kẹt cơ học tại vùng tiếp điểm, nhưng không hỏng.", "Đèn bị đấu nhầm vào chân NC thay vì NO.", "Điện áp đầu vào là 12V quá nhỏ so với 220V để làm sáng đèn.", "Khi cấp dòng điện 3A, tiếp điểm tự động ngắt vì không đủ 5A để hoạt động."], "correctIndex": 1, "explain": "<i class=\"canh-bao-lg\">(Lưu ý: lời giải gốc ghi đáp án C, còn đáp án tô trong đề là B — web đang dùng B.)</i><br><b>Giải thích đáp án từ câu 106-108</b><br><b>Câu 106. Đáp án đúng: C.</b><br>Theo đề bài: “mạch Relay dùng một mạch điều khiển công suất nhỏ để đóng/ngắt một mạch công suất lớn hơn”<br><b>Câu 107. Đáp án C. </b><br>Theo đề bài, Khi <b>chưa cấp điện</b> vào cuộn dây<b> C nối với NC (mạch thường đóng).</b><br><b>Câu 108. Đáp án B:</b><br>Trạng thái <b>chưa cấp 12V</b> (ban ngày): rơle ở trạng thái nghỉ → chân C nối với <b>NC</b>.<br>Nếu đèn đấu vào <b>NC</b>, mạch 220V sẽ kín ngay khi cuộn dây không có điện → <b>ban ngày đèn sáng</b>.<br>Khi <b>cấp 12V</b> (ban đêm): cuộn dây tạo từ trường, rơle hút → chân C chuyển sang <b>NO</b>, tách khỏi NC → mạch qua NC bị ngắt → <b>đèn tắt</b>.<br>Các dữ kiện nhiễu:<br>Dòng 3A &lt; 5A → không quá tải.<br>220V ổn định → không do nguồn.<br>Rơle không cháy → không do hỏng cơ học.<br>⇒ Hệ thống đã <b>đấu nhầm vào chân NC thay vì NO</b>."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SINH - Dựa vào thông tin dưới đây để trả lời các Câu từ 109 đến 111</b><br>Giống lúa Việt Lai 20 là giống lúa lai cao sản, được tạo ra nhờ ứng dụng của phương pháp tạo ưu thế lai. ở trà vụ Xuân là 110 - 115 ngày, thời gian sinh trưởng ở trà vụ mùa là 85 - 90 ngày. Đây là giống lúa có kiểu hình đẹp, cây gọn, cứng, chiều cao cây khoảng 90 - 95cm, bông dài dài 25 - 27 cm, có từ 150 - 160 hạt chắc/bông. Hạt thuôn dài, màu vàng sẫm, chiều dài hạt trung bình khoảng 7 - 7,5mm, tỉ lệ chiều dài/rộng hạt là 2,94, trọng lượng 1000 hạt: 29 - 30 gram. Gạo trong, ít bạc bụng, hàm lượng amylose (%): 20,7. Hạt gạo trong, cơm mềm, dẻo, vị đậm, mùi thơm nhẹ, tỷ lệ hạt chắc trên bông cao, tỷ lệ hạt lép thấp.<br>Việt Lai 20 là giống lúa có tỷ lệ nảy mầm cao, khả năng đẻ nhánh tốt, cho số rãnh hữu hiệu cao. Lúa có khả năng sinh trưởng và phát triển tốt, khả năng chịu rét và chịu nóng khá, chống đổ khá, chịu chua, mặn và chịu hạn khá. Về khả năng chống chịu sâu bệnh, Việt Lai 20 là giống kháng vừa với bệnh Đạo ôn và bệnh Bạc lá, nhiễm nhẹ với bệnh Khô vằn và Rầy nâu.<br><img class=\"anh-de\" src=\"data/anh/l7/c2ebd5ecd096a862.png\" alt=\"\" style=\"width:246px;height:139px\">Giống Việt Lai 20 có khả năng thích ứng rộng trên nhiều loại đất, sinh trưởng, phát triển khoẻ, chịu rét chịu hạn tốt và năng suất rất cao, trung bình từ 7,0 đến 7,5 tấn/ha. Một người nông dân mua giống này về trồng ở vụ đông xuân, năng suất khi thu hoạch là 7,2 tấn/ha; một phần hạt được tích trữ để làm giống gieo trồng cho vụ sau. Tuy nhiên, năng suất vụ sau đạt được chỉ còn 5,8 tấn/ha. Giả định rằng các điều kiện sinh thái môi trường và kỹ thuật canh tác ở hai vụ là như nhau; phần lớn bông lúa sinh sản tự thụ phấn và một phần nhỏ thụ phấn chéo nhờ gió, côn trùng.", "cauHoi": [{"question": "Hiện tượng sử dụng hạt thu hoạch ở vụ trước làm giống cho vụ sau mà năng suất giảm là một ví dụ của hiện tượng", "choices": ["đột biến.", "ưu thế lai.", "thoái hóa giống.", "biến dị tổ hợp."], "correctIndex": 2, "explain": "<b>Câu 109. Chọn C.</b><br>Hướng dẫn: Sử dụng hạt thu hoạch ở vụ trước làm giống cho vụ sau làm tăng tỉ lệ kiểu gen đồng<br>hợp, giảm tỉ lệ kiểu gen dị hợp =&gt; Giảm ưu thế lai, năng suất, chất lượng giảm đó là ví dụ của hiện<br>tượng thoái hóa giống =&gt; Đáp án C."}, {"question": "Cơ sở khoa học của hiện tượng năng suất của lúa Việt Lai 20 cao khi mua giống tại trung tâm sản xuất giống là gì?", "choices": ["Giống lúa Việt Lai 20 có kiểu gene chứa các gene ở trạng thái dị hợp.", "Giống lúa Việt Lai 20 có kiểu gene chứa các gene ở trạng thái đồng hợp.", "Giống lúa Việt Lai 20 có kiểu gene chứa các gene ở trạng thái đồng hợp trội.", "Giống lúa Việt Lai 20 có kiểu gene chứa các gene ở trạng thái đồng hợp lặn"], "correctIndex": 0, "explain": "<b>Câu 110. Chọn A.</b><br>Hướng dẫn: Giống lúa Việt Lai 20 là giống lúa lai cao sản, được tạo ra nhờ ứng dụng của phương<br>pháp tạo ưu thế lai nên có ưu thế lai cao, tỷ lệ các gene dị hợp trong kiểu gene cao =&gt; Đáp án A."}, {"question": "Phát biểu nào sau đây là đúng?", "choices": ["Hiện tượng giảm năng suất ở vụ sau có thể được xem là ví dụ về thường biến.", "Nếu không xảy ra hiện tượng thụ phấn chéo thì năng suất vụ sau sẽ ổn định như vụ đầu.", "Năng suất ở vụ sau giảm là do tỉ lệ các cây lúa mang kiểu gene dị hợp về năng suất được trồng ở vụ sau nhiều hơn so với tỉ lệ tương ứng ở vụ đầu.", "Để tiếp tục thu hoạch được năng suất từ 7,0 đến 7,5 tấn/ha, người nông dân nên mua lại giống Việt Lai 20 từ nhà sản xuất và gieo trồng với điều kiện sinh thái và kỹ thuật canh tác như vụ đầu"], "correctIndex": 3, "explain": "<b>Câu 111. Chọn D.</b><br>Hướng dẫn:<br>Giống lúa Việt Lai 20 là giống lúa lai cao sản do Trung tâm giống lai tạo ra, người nông dân muốn<br>có năng suất tối ưu của giống thì cần tới các Trung tâm giống để mua hạt giống về gieo trồng<br>=&gt; Đáp án D"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN ĐỊA - Dựa vào thông tin dưới đây để trả lời các Câu từ 112 đến 114 </b><br>“Từ năm 2011 trở về trước, cán cân thương mại hàng hóa của Việt Nam luôn trong trạng thái thâm hụt, kéo dài liên tục; nhập siêu đạt đỉnh 18,02 tỉ USD vào năm 2008.<br>Từ năm 2012 đến nay, cán cân thương mại hàng hóa đã chuyển sang thặng dư (xuất siêu) liên tục, trừ năm 2015 thâm hụt 3,55 tỉ USD.<br>Năm 2020, cán cân thương mại đạt kỷ lục thặng dư 19,94 tỉ USD. Kết thúc năm 2021, thặng dư giảm còn 3,32 tỉ USD.<br>Trong 11 tháng đầu năm 2022, do xuất khẩu tăng cao hơn nhập khẩu, thặng dư thương mại đạt 10,68 tỉ USD.<br>Trong 11 tháng đầu năm 2022, tổng trị giá xuất nhập khẩu của nhóm doanh nghiệp FDI đạt 468,7 tỉ USD, tăng 12,1% so với cùng kỳ năm 2021.<br>Chính phủ đã chỉ đạo Bộ Tài chính phối hợp với các bộ, ngành, địa phương thực hiện đồng bộ các giải pháp nhằm tạo môi trường kinh doanh bình đẳng, thông thoáng, minh bạch, thuận lợi hơn cho cộng đồng doanh nghiệp.”", "cauHoi": [{"question": "Trong 11 tháng đầu năm 2022, tổng trị giá xuất nhập khẩu của nhóm doanh nghiệp FDI tăng bao nhiêu phần trăm so với cùng kỳ năm 2021?", "choices": ["10,5%", "11,3%", "12,1%", "13,7%"], "correctIndex": 2, "explain": "<b>Giải: </b>Đề bài nêu rõ: “... đạt 468,7 tỉ USD, <b>tăng 12,1%</b> so với cùng kỳ năm 2021.”<br>→ Đáp án đúng: <b>C. 12,1%</b>"}, {"question": "Mức thâm hụt cán cân thương mại hàng hóa của Việt Nam trong năm 2015 là bao nhiêu?", "choices": ["3,55 tỉ USD", "10,68 tỉ USD", "19,94 tỉ USD", "18,02 tỉ USD"], "correctIndex": 0, "explain": "<b>Giải: </b>Đề bài ghi: “... trừ năm 2015 thâm hụt <b>3,55 tỉ USD</b>.”<br>→ Đáp án đúng: <b>A. 3,55 tỉ USD</b>"}, {"question": "Chính phủ đã chỉ đạo Bộ Tài chính phối hợp thực hiện các giải pháp nhằm mục đích gì?", "choices": ["Tăng cường xuất khẩu", "Giảm nhập khẩu", "Tạo môi trường kinh doanh bình đẳng, thông thoáng, minh bạch", "Hỗ trợ doanh nghiệp FDI"], "correctIndex": 2, "explain": "<b>Giải: </b>Đoạn cuối nêu rõ mục tiêu là:<br>“... nhằm <b>tạo môi trường kinh doanh bình đẳng, thông thoáng, minh bạch</b>...”<br>→ Đáp án đúng: <b>C. Tạo môi trường kinh doanh bình đẳng, thông thoáng, minh bạch</b>"}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN SỬ - Dựa vào thông tin dưới đây để trả lời các Câu từ 115 đến 117</b><br>“Cuộc phản công thắng lợi ở Việt Bắc và chiến tranh nổi mạnh ở miền Nam đã gây thêm tinh thần nỗ lực phấn khởi trong toàn dân, tăng thêm tin tưởng ở tiền đồ kháng chiến vẻ vang của dân tộc. Nó chứng tỏ Việt Nam nước nhỏ, không có căn cứ địa vững chắc, biên giới có thể bị bao vây, vũ khí kém, nhưng với sự đoàn kết cố gắng của toàn dân, dưới chế độ dân chủ cộng hòa, dưới sự lãnh đạo vừa kháng chiến vừa kiến quốc của Chính phủ Hồ Chí Minh và của Đảng, vẫn có thể kháng chiến thắng lợi”<br>(Đảng Cộng sản Việt Nam, Văn kiện Đảng toàn tập, tập 9,<br>Nxb. Chính trị quốc gia, Hà Nội, 2000, tr. 20-21)", "cauHoi": [{"question": "Chiến dịch Việt Bắc thu đông năm 1947 không diễn ra trong bối cảnh nào sau đây?", "choices": ["Nhân dân Việt Nam đã trở thành người làm chủ đất nước", "Chênh lệch lực lượng giữa ta và Pháp còn khá lớn.", "Phong trào giải phóng dân tộc ở các nước thuộc địa phát triển.", "Đế quốc Mỹ trực tiếp can thiệp vào tình hình Việt Nam."], "correctIndex": 3, "explain": "<b>Đáp án: D. Đế quốc Mỹ trực tiếp can thiệp vào tình hình Việt Nam.</b><br>Giải thích: - 1949, Mỹ bắt đầu can thiệp, dính líu vào cuộc chiến tranh xâm lược Đông Dương của thực dân Pháp.<br>- Bước sang giai đoạn 1951 -1953, đế quốc Mĩ từng bước can thiệp vào Đông Dương thông qua các hiệp định:<br>+ Ngày 23/12/1950, Mĩ kí với Pháp Hiệp định phòng thủ chung Đông Dương. Thực chất, thực dân Pháp muốn dựa vào viện trợ của Mĩ để tìm cách xoay chuyển tình hình, giành lại thế chủ động trên chiến trường.<br>+ Tháng 9/1951, Mĩ kí với Bảo Đại Hiệp ước hợp tác kinh tế Việt – Mĩ nhằm ràng buộc Chính phủ Bảo Đại vào Mĩ."}, {"question": "Chiến dịch Việt Bắc thu đông năm 1947 thắng lợi đã giành được kết quả nào sau đây?", "choices": ["Sự nghiệp kháng chiến – kiến quốc của nhân dân Việt Nam kết thúc thắng lợi.", "Quân Pháp rút khỏi Việt Bắc, cơ quan đầu não kháng chiến được bảo toàn.", "Khai thông đường biên giới Việt – Trung, tạo điều kiện liên lạc với quốc tế.", "Quân đội Việt Nam giành được thế chủ động trên chiến trường chính Bắc Bộ."], "correctIndex": 1, "explain": "<b>Đáp án: B. Quân Pháp rút khỏi Việt Bắc, cơ quan đầu não kháng chiến được bảo toàn.</b><br>Giải thích: Kết quả của chiến dịch Việt Bắc thu – đông năm 1947<br>+ Buộc đại bộ phận quân Pháp phải rút chạy khỏi Việt Bắc (ngày 19/12/1947).<br>+ Căn cứ địa Việt Bắc và cơ quan đầu não kháng chiến được bảo toàn.<br>- Loại khỏi vòng chiến đấu hàng nghìn quân địch, phá hủy, thu nhiều vũ khí."}, {"question": "Các nhận định nào sau đây là đúng về ý nghĩa của chiến dịch Việt – Bắc thu đông (năm 1947)?<br>I. Chiến dịch Việt Bắc thu đông (1947) đã chứng minh tính đúng đắn của đường lối kháng chiến do Đảng đề ra.<br>II. Chiến dịch Việt Bắc thu đông (1947) làm phá sản hoàn toàn âm mưu đánh nhanh thắng nhanh của thực dân Pháp.<br>III. Chiến dịch Việt Bắc (1947) là chiến dịch chủ động tiến công của quân đội Việt Nam, buộc Pháp phải chuyển sang đánh lâu dài.<br>IV. Chiến dịch Việt Bắc thu đông (1947) mang hình thái chiến tranh nhân dân, huy động toàn dân đánh giặc.", "choices": ["I,II và III.", "I,II và IV.", "I,III và IV.", "II,III và IV."], "correctIndex": 1, "explain": "<b>Đáp án: B. I,II và IV.</b><br>Giải thích:<br>• Nhận định I đúng vì: Đường lối toàn dân, toàn diện, trường kỳ kháng chiến, tự lực cánh sinh<br>của Đảng đã được kiểm chứng qua thắng lợi của chiến dịch.<br>• Nhận định II đúng vì: Chiến dịch Việt Bắc thu đông (1947) làm phá sản hoàn toàn âm mưu đánh<br>nhanh thắng nhanh của thực dân Pháp. Sau thất bại này, Pháp buộc phải chuyển sang chiến lược<br>đánh lâu dài.<br>• Nhận định III sai vì: Đây là chiến dịch phản công lớn của ta, không phải chiến dịch chủ động<br>tiến công.<br>• Nhận định IV đúng vì: Chiến dịch thể hiện rõ tinh thần toàn dân tham gia kháng chiến, từ bộ<br>đội chủ lực, dân quân du kích đến nhân dân hỗ trợ hậu cần."}], "khongXaoTron": true}, {"noiDungChung": "<b>MÔN KTPL - Dựa vào thông tin dưới đây để trả lời các Câu từ 118 đến 120 </b><br>Ngày 16/11/2013, Quốc hội ban hành Luật Việc làm, trong đó đã chuyển các quy định về chính sách bảo hiểm thất nghiệp từ Luật Bảo hiểm xã hội để sửa đổi, bổ sung và chính thức thực hiện theo quy định của Luật Việc làm từ ngày 1/1/2015. Chính sách bảo hiểm thất nghiệp được thực hiện để: chi trả trợ cấp thất nghiệp, đóng bảo hiểm y tế cho người hưởng trợ cấp thất nghiệp; hỗ trợ đào tạo, bồi dưỡng, nâng cao trình độ, kỹ năng nghề để duy trì việc làm cho người lao động; hỗ trợ tư vấn, giới thiệu việc làm; hỗ trợ học nghề... Tính tới hết năm 2023, số người tham gia bảo hiểm thất nghiệp tăng từ gần 6 triệu người năm 2009 lên hơn 14,6 triệu tăng hơn 2,4 lần.<br>(Nguồn: https://nhandan.vn ngày 15/02/2023)", "cauHoi": [{"question": "Theo thông tin trên, Luật Việc làm được Quốc hội ban hành nhằm mục đích chính nào sau đây?", "choices": ["Hỗ trợ doanh nghiệp tăng cường tuyển dụng lao động mới.", "Đảm bảo an sinh xã hội thông qua bảo hiểm thất nghiệp.", "Chuyển đổi quy định từ Luật Lao động sang Luật Việc làm.", "Tăng cường đào tạo lao động để phát triển kinh tế quốc gia"], "correctIndex": 1, "explain": "Câu 118. Chọn B<br>Giải thích:<br>Đáp án đúng: B. Vì mục tiêu chính của Luật Việc làm là đảm bảo an sinh xã hội thông qua các chính sách bảo hiểm thất nghiệp.<br>A, C, và D đều sai vì chỉ tập trung vào những khía cạnh phụ hoặc không phù hợp với mục đích chính của luật"}, {"question": "Dựa vào thông tin , đâu là yếu tố quan trọng nhất giúp tăng số người tham gia bảo hiểm thất nghiệp từ 6 triệu năm 2009 lên hơn 14,6 triệu năm 2023?", "choices": ["Việc chuyển quy định từ Luật Bảo hiểm xã hội sang Luật Việc làm từ năm 2015.", "Tăng cường nhận thức của người lao động về lợi ích của bảo hiểm thất nghiệp.", "Sự mở rộng của các nội dung hỗ trợ như đào tạo nghề, tư vấn việc làm.", "Sự cải thiện các quy trình quản lý, đảm bảo tính minh bạch và hiệu quả khi chi trả trợ cấp thất nghiệp."], "correctIndex": 2, "explain": "<b>Câu 119. Chọn đáp án C</b> phản ánh chính xác tác động của các nội dung hỗ trợ như đào tạo nghề, tư vấn việc làm và nâng cao kỹ năng nghề – yếu tố then chốt thu hút người lao động tham gia bảo hiểm thất nghiệp.<br>• Các đáp án A, B. D chỉ là các yếu tố hỗ trợ hoặc gián tiếp, không phải yếu tố quan trọng nhất dẫn đến sự gia tăng lớn trong số lượng người tham gia bảo hiểm thất nghiệp."}, {"question": "Nếu bạn là nhà hoạch định chính sách, bạn sẽ đề xuất biện pháp nào để tăng cường tác động của bảo hiểm thất nghiệp, đặc biệt đối với người lao động cần nâng cao kỹ năng nghề và tìm việc làm?", "choices": ["Tăng mức trợ cấp thất nghiệp để đảm bảo người lao động có tài chính ổn định hơn trong thời gian chưa tìm được việc làm.", "Xây dựng các trung tâm đào tạo nghề liên kết với doanh nghiệp, kết hợp tư vấn nghề nghiệp và tuyển dụng lao động thất nghiệp.", "Đơn giản hóa quy trình giải quyết trợ cấp thất nghiệp và giảm chi phí tham gia bảo hiểm.", "Tập trung nâng cao mức trợ cấp thất nghiệp để khuyến khích người lao động tham gia chính sách bảo hiểm."], "correctIndex": 1, "explain": "<b>Câu 120. Đáp án đúng: B.</b> Giải pháp này đáp ứng toàn diện các mục tiêu của bảo hiểm thất nghiệp, giúp người lao động cải thiện kỹ năng, tăng cơ hội việc làm, và tái hòa nhập thị trường lao động.<br>• Các phương án A, B. D khác chỉ tập trung vào khía cạnh ngắn hạn hoặc hỗ trợ hành chính, không mang lại tác động sâu rộng và lâu dài.."}], "khongXaoTron": true}]};
